pre-actions.script:
if (!ec.user.userId) { ec.web.saveScreenLastInfo(null, null); sri.sendRedirectAndStopRender('/Login') }

String instancePurpose = System.getProperty("instance_purpose")
if (!instancePurpose || instancePurpose == 'production') {
    html_scripts.add('/qapps2static/js/CombinedBase.min.js')
    footer_scripts.add('/qapps2static/js/CombinedQvt2.min.js')
} else {
    html_scripts.add('/qapps2static/libs/moment.js/moment-with-locales.min.js')
    html_scripts.add('/qapps2static/libs/jquery/jquery.min.js')
    html_scripts.add('/qapps2static/js/MoquiLib.js')
    footer_scripts.add('/qapps2static/libs/vue3/vue.global.js')
    footer_scripts.add('/qapps2static/libs/vue3-sfc-loader/vue3-sfc-loader.js')
    footer_scripts.add('/qapps2static/libs/quasar2/quasar.umd.prod.js')
    footer_scripts.add('/qapps2static/libs/quasar2/lang/zh-CN.umd.prod.js')
    footer_scripts.add('/qapps2static/js/WebrootVue.qvt2.js')
}
